code.cpp:
class Solution {
public:
    int maximumScore(vector<int>& scores, vector<vector<int>>& edges) {
        int n = scores.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<vector<int>> top3(n);
        for (int i = 0; i < n; i++) {
            int a = -1, b = -1, c = -1;
            for (int nb : adj[i]) {
                if (a == -1 || scores[nb] > scores[a]) {
                    c = b; b = a; a = nb;
                } else if (b == -1 || scores[nb] > scores[b]) {
                    c = b; b = nb;
                } else if (c == -1 || scores[nb] > scores[c]) {
                    c = nb;
                }
            }
            if (a != -1) top3[i].push_back(a);
            if (b != -1) top3[i].push_back(b);
            if (c != -1) top3[i].push_back(c);
        }
        long long ans = -1;
        for (auto& e : edges) {
            int u = e[0], v = e[1];
            for (int a : top3[u]) {
                if (a == v) continue;
                for (int b : top3[v]) {
                    if (b == u || b == a) continue;
                    long long s = (long long)scores[a] + scores[u] + scores[v] + scores[b];
                    if (s > ans) ans = s;
                }
            }
        }
        return (int)ans;
    }
};
